-- 01_ask_kb_followups_test.sql: runs the migration's statements, checks them, runs the insert a second time (must add
-- nothing), and rolls everything back by raising 'RESULT: ...'. Nothing is kept. NOT RUN by the helper (it writes inside a
-- transaction and the server is read-only for helpers). Expect the error text to start with: RESULT: PASS
do $t$
declare n0 int; n1 int; n2 int; r int; mx0 int; vn int; act jsonb;
begin
  select count(*), max(ord) into n0, mx0 from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  execute $st$insert into pb_ai.kb_chunks (version, ord, lib, chunk)
select 'b3e91f6c47d2', m.mx + t.i, 'field', t.e
  from jsonb_array_elements($kb$[{"id": "plan-wa-trench-1", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-657.htm", "text": "Washington runs its own OSHA plan (DOSH, at Labor and Industries) and its excavation rule is chapter 296-155 WAC, Part N. It is stricter than federal OSHA in three ways a crew will feel. 1) Depth: every employee in an excavation must be protected from cave-ins by a protective system (sloping, benching, shoring or a shield) unless the excavation is entirely in stable rock, or it is less than 4 ft deep and a competent person has examined the ground and found no indication of a potential cave-in (WAC 296-155-657(1)(a)). Federal OSHA draws that line at 5 ft. 2) Written plan, since June 1, 2026: the employer must have a competent person complete a written trench excavation work plan for any trench an employee may enter where a protective system is required; employees are trained on the plan before they go in, and the plan is kept on the job site. No written plan is needed when the trench is 4 ft or less and no protective system is required, or when the trench is sloped at 1.5 horizontal to 1 vertical or flatter (WAC 296-155-655(13)). 3) Competent person on site: a competent person must remain on the job site any time trench excavation work is being performed (WAC 296-155-655(13)(a)), and inspects the excavation, the area around it and the protective system daily, before work starts, as needed during the shift and after every rainstorm (WAC 296-155-655(11)). The rest matches the federal numbers: a ladder, stairway or ramp in trenches 4 ft or more deep with no more than 25 ft of lateral travel; spoil and equipment at least 2 ft back from the edge; test the air before entering an excavation deeper than 4 ft where a hazardous atmosphere could exist; digging up to 2 ft below the bottom of a shield only when the shield is rated for the full depth and no soil is being lost from behind or below it; sloping or benching for an excavation deeper than 20 ft designed by a registered professional engineer. Plain-language summary; the WAC text, your competent person and your company program govern.", "title": "Washington trench rules (WAC 296-155 Part N): protective system at 4 ft, written trench work plan, competent person on site", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "WAC 296-155-657(1)(a), (7)(b); WAC 296-155-655(3), (7), (10), (11), (13) as amended by WSR 26-09-113 (effective June 1, 2026); checked 2026-11-20", "confidence": "high", "state": "WA"}, {"id": "plan-wa-trench-2", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-66403.htm", "text": "Washington's sloping table is Table N-1 in WAC 296-155-66403 (Part N, Appendix B). Maximum allowable slopes, horizontal to vertical, for excavations less than 20 ft deep: stable rock vertical (90 degrees); Type A soil 3/4 to 1 (53 degrees); Type B soil 1 to 1 (45 degrees); Type C soil 1 1/2 to 1 (34 degrees). Sloping or benching for an excavation deeper than 20 ft must be designed by a registered professional engineer. Where it differs from the federal table: the federal table (29 CFR 1926 Subpart P, Appendix B, Table B-1) has a note allowing a steeper short-term slope of 1/2 to 1 in Type A soil for excavations 12 ft or less that are open 24 hours or less. Table N-1 has no such note and the Washington appendix has no short-term allowance, so on a Washington job Type A is 3/4 to 1 no matter how short a time the trench is open. The Type A, B and C angles themselves are the same as federal. When the slope shows signs of distress, cut it back at least 1/2 horizontal to 1 vertical flatter than the maximum allowable slope. In the app's Trench Sloping screen, pick plain Type A (0.75:1) on a Washington job; its 'Type A, short-term' choice (0.5:1) is the federal note and is not in Washington's table. And remember that Washington requires protection from 4 ft, not 5 ft. The competent person classifies the soil and picks the slope; this is a plain-language summary and the WAC text governs.", "title": "Washington trench sloping (WAC 296-155-66403, Table N-1): maximum slopes by soil type, no steeper short-term slope in Type A", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "WAC 296-155-66403 Table N-1 and notes (WSR 16-09-085); 29 CFR 1926 Subpart P Appendix B, Table B-1 note 2; checked 2026-11-20", "confidence": "high", "state": "WA"}]$kb$::jsonb) with ordinality as t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where exists (select 1 from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2')
   and not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' in ('plan-wa-trench-1', 'plan-wa-trench-2'))$st$; get diagnostics r = row_count;
  if r <> 2 then raise exception 'FAIL insert count % (ids already there, or the KB version changed)', r; end if;
  execute $st$update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2'$st$;
  execute $st$update pb_ai.kb_index set parts = 32 where version = 'b3e91f6c47d2'$st$;
  select count(*) into n1 from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  select n into vn from pb_ai.kb_versions where version = 'b3e91f6c47d2';
  act := public.pb_ai_kb_active();
  if n1 <> n0 + 2 then raise exception 'FAIL rows % -> %', n0, n1; end if;
  if vn <> n1 or (act->>'n')::int <> n1 then raise exception 'FAIL kb_versions.n % / active % vs rows %', vn, act->>'n', n1; end if;
  if (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and ord > mx0 and lib = 'field' and chunk->>'state' = 'WA' and chunk->>'id' in ('plan-wa-trench-1', 'plan-wa-trench-2')) <> 2 then raise exception 'FAIL new ids'; end if;
  if (select count(distinct chunk->>'id') from pb_ai.kb_chunks where version = 'b3e91f6c47d2') <> n1 then raise exception 'FAIL duplicate chunk id'; end if;
  if (select count(distinct ord) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') <> n1 then raise exception 'FAIL duplicate ord'; end if;
  if coalesce(jsonb_typeof(public.pb_ai_kb_boot()->'index'), 'null') = 'object' then raise exception 'FAIL the old index blob would still be used'; end if;
  execute $st$insert into pb_ai.kb_chunks (version, ord, lib, chunk)
select 'b3e91f6c47d2', m.mx + t.i, 'field', t.e
  from jsonb_array_elements($kb$[{"id": "plan-wa-trench-1", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-657.htm", "text": "Washington runs its own OSHA plan (DOSH, at Labor and Industries) and its excavation rule is chapter 296-155 WAC, Part N. It is stricter than federal OSHA in three ways a crew will feel. 1) Depth: every employee in an excavation must be protected from cave-ins by a protective system (sloping, benching, shoring or a shield) unless the excavation is entirely in stable rock, or it is less than 4 ft deep and a competent person has examined the ground and found no indication of a potential cave-in (WAC 296-155-657(1)(a)). Federal OSHA draws that line at 5 ft. 2) Written plan, since June 1, 2026: the employer must have a competent person complete a written trench excavation work plan for any trench an employee may enter where a protective system is required; employees are trained on the plan before they go in, and the plan is kept on the job site. No written plan is needed when the trench is 4 ft or less and no protective system is required, or when the trench is sloped at 1.5 horizontal to 1 vertical or flatter (WAC 296-155-655(13)). 3) Competent person on site: a competent person must remain on the job site any time trench excavation work is being performed (WAC 296-155-655(13)(a)), and inspects the excavation, the area around it and the protective system daily, before work starts, as needed during the shift and after every rainstorm (WAC 296-155-655(11)). The rest matches the federal numbers: a ladder, stairway or ramp in trenches 4 ft or more deep with no more than 25 ft of lateral travel; spoil and equipment at least 2 ft back from the edge; test the air before entering an excavation deeper than 4 ft where a hazardous atmosphere could exist; digging up to 2 ft below the bottom of a shield only when the shield is rated for the full depth and no soil is being lost from behind or below it; sloping or benching for an excavation deeper than 20 ft designed by a registered professional engineer. Plain-language summary; the WAC text, your competent person and your company program govern.", "title": "Washington trench rules (WAC 296-155 Part N): protective system at 4 ft, written trench work plan, competent person on site", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "WAC 296-155-657(1)(a), (7)(b); WAC 296-155-655(3), (7), (10), (11), (13) as amended by WSR 26-09-113 (effective June 1, 2026); checked 2026-11-20", "confidence": "high", "state": "WA"}, {"id": "plan-wa-trench-2", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-66403.htm", "text": "Washington's sloping table is Table N-1 in WAC 296-155-66403 (Part N, Appendix B). Maximum allowable slopes, horizontal to vertical, for excavations less than 20 ft deep: stable rock vertical (90 degrees); Type A soil 3/4 to 1 (53 degrees); Type B soil 1 to 1 (45 degrees); Type C soil 1 1/2 to 1 (34 degrees). Sloping or benching for an excavation deeper than 20 ft must be designed by a registered professional engineer. Where it differs from the federal table: the federal table (29 CFR 1926 Subpart P, Appendix B, Table B-1) has a note allowing a steeper short-term slope of 1/2 to 1 in Type A soil for excavations 12 ft or less that are open 24 hours or less. Table N-1 has no such note and the Washington appendix has no short-term allowance, so on a Washington job Type A is 3/4 to 1 no matter how short a time the trench is open. The Type A, B and C angles themselves are the same as federal. When the slope shows signs of distress, cut it back at least 1/2 horizontal to 1 vertical flatter than the maximum allowable slope. In the app's Trench Sloping screen, pick plain Type A (0.75:1) on a Washington job; its 'Type A, short-term' choice (0.5:1) is the federal note and is not in Washington's table. And remember that Washington requires protection from 4 ft, not 5 ft. The competent person classifies the soil and picks the slope; this is a plain-language summary and the WAC text governs.", "title": "Washington trench sloping (WAC 296-155-66403, Table N-1): maximum slopes by soil type, no steeper short-term slope in Type A", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "WAC 296-155-66403 Table N-1 and notes (WSR 16-09-085); 29 CFR 1926 Subpart P Appendix B, Table B-1 note 2; checked 2026-11-20", "confidence": "high", "state": "WA"}]$kb$::jsonb) with ordinality as t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where exists (select 1 from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2')
   and not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' in ('plan-wa-trench-1', 'plan-wa-trench-2'))$st$; get diagnostics r = row_count;
  select count(*) into n2 from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if r <> 0 or n2 <> n1 then raise exception 'FAIL second run added % rows', r; end if;
  raise exception 'RESULT: PASS rows % -> %, n %, rerun added 0 (rolled back)', n0, n1, vn;
end $t$;
